import { useContext, useEffect, useState, useCallback } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import './notifications.scss';

const Notifications = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);
  const navigate = useNavigate();
  const [friendRequests, setFriendRequests] = useState([]);
  const [messageNotifications, setMessageNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [fetched, setFetched] = useState(false);

  console.log('Notifications: Initial render, currentUser=', currentUser ? JSON.stringify(currentUser, null, 2) : 'null');
  console.log('Notifications: sessionStorage.accessToken=', sessionStorage.getItem('accessToken') || 'null');

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('Notifications: No profile picture provided, using default');
      return '/assets/default-avatar.png';
    }
    if (profilePicture.startsWith('http')) {
      console.log('Notifications: Using external profile picture URL:', profilePicture);
      return profilePicture;
    }
    const normalizedPath = profilePicture.replace(/^\/Uploads\//i, '/Uploads/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('Notifications: Profile picture URL:', url);
    return url;
  };

  const fetchNotifications = useCallback(async () => {
    setLoading(true);
    setError(null);
    const token = sessionStorage.getItem('accessToken');
    if (!token) {
      console.error('Notifications: No accessToken found in sessionStorage');
      setError('Please log in to view notifications.');
      setLoading(false);
      setFetched(true);
      navigate('/login');
      return;
    }

    try {
      console.log('Notifications: Fetching friend requests from: http://localhost:5000/api/users/friend-requests/pending');
      const friendReqRes = await axios.get('http://localhost:5000/api/users/friend-requests/pending', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const friendRequestsData = Array.isArray(friendReqRes.data) ? friendReqRes.data : [];
      console.log('Notifications: Friend requests response:', JSON.stringify(friendReqRes.data, null, 2));

      const validatedFriendRequests = friendRequestsData.filter((req) => {
        const isValid = req.senderId &&
                       req.senderId._id &&
                       /^[0-9a-fA-F]{24}$/.test(req.senderId._id) &&
                       req.senderId.username &&
                       req.senderId.name &&
                       req.status === 'pending';
        if (!isValid) {
          console.warn('Notifications: Invalid friend request data:', JSON.stringify(req, null, 2));
        }
        return isValid;
      });
      console.log('Notifications: Validated friend requests:', JSON.stringify(validatedFriendRequests, null, 2));
      setFriendRequests(validatedFriendRequests);

      console.log('Notifications: Fetching message notifications from: http://localhost:5000/api/messages/notifications');
      const msgRes = await axios.get('http://localhost:5000/api/messages/notifications', {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('Notifications: Message notifications response:', JSON.stringify(msgRes.data, null, 2));
      const validMessages = (msgRes.data || []).filter((msg) => {
        const isValid = msg.senderId?._id &&
                       /^[0-9a-fA-F]{24}$/.test(msg.senderId._id) &&
                       msg.senderId.username &&
                       msg.content;
        if (!isValid) {
          console.warn('Notifications: Skipping invalid message notification:', JSON.stringify(msg, null, 2));
        }
        return isValid;
      });
      console.log('Notifications: Validated message notifications:', JSON.stringify(validMessages, null, 2));
      setMessageNotifications(validMessages);

      setError(null);
      setFetched(true);
    } catch (err) {
      console.error('Notifications: Error fetching notifications:', err.message);
      console.error('Notifications: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
      });
      let errorMessage = 'Failed to load notifications.';
      if (err.response?.status === 401) {
        errorMessage = 'Session expired. Please log in again.';
        sessionStorage.removeItem('accessToken');
        sessionStorage.removeItem('user');
        navigate('/login');
      } else if (err.response?.status === 404) {
        errorMessage = 'No notifications found.';
      }
      setError(errorMessage);
      setFriendRequests([]);
      setMessageNotifications([]);
      setFetched(true);
    } finally {
      setLoading(false);
      console.log('Notifications: fetchNotifications completed, loading=', false);
    }
  }, [navigate]);

  useEffect(() => {
    if (!currentUser) {
      console.log('Notifications: No currentUser, redirecting to login');
      setError('Please log in to view notifications.');
      navigate('/login');
      return;
    }
    console.log('Notifications: Fetching notifications for user:', currentUser.id);
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 10000);
    return () => {
      console.log('Notifications: Cleaning up polling interval');
      clearInterval(interval);
    };
  }, [currentUser, fetchNotifications, navigate]);

  const handleFriendRequestAction = async (senderId, action) => {
    try {
      const token = sessionStorage.getItem('accessToken');
      if (!token) {
        throw new Error('No access token available');
      }
      const status = action === 'accept' ? 'accepted' : 'rejected';
      console.log(`Notifications: ${action}ing friend request from senderId: ${senderId}`);
      const res = await axios.post(
        `http://localhost:5000/api/users/friend-requests/${senderId}`,
        { action: status },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      console.log(`Notifications: Friend request ${status}:`, res.data);
      setFriendRequests(friendRequests.filter((req) => req.senderId._id !== senderId));
      alert(`Friend request ${status} successfully!`);
    } catch (err) {
      console.error(`Notifications: Error ${action}ing friend request:`, err.message);
      console.error('Notifications: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
      });
      const errorMessage = err.response?.data?.message || `Failed to ${action} friend request.`;
      setError(errorMessage);
    }
  };

  const handleMessageClick = (senderId) => {
    console.log('Notifications: Navigating to messages for senderId:', senderId);
    if (!senderId || !/^[0-9a-fA-F]{24}$/.test(senderId)) {
      console.error('Notifications: Invalid senderId:', senderId);
      setError('Invalid user ID for message navigation.');
      return;
    }
    navigate(`/messages/${senderId}`);
  };

  console.log('Notifications: Rendering with state:', {
    loading,
    error,
    fetched,
    friendRequests: friendRequests.length,
    messageNotifications: messageNotifications.length,
  });

  if (!currentUser) {
    console.log('Notifications: Rendering no currentUser state');
    return <div className={`notifications ${darkMode ? 'theme-dark' : 'theme-light'}`}>Please log in to view notifications.</div>;
  }

  return (
    <div className={`notifications ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <h3>Notifications</h3>
      {loading && <p className="loading">Loading notifications...</p>}
      {error && <p className="error">{error}</p>}
      {fetched && !loading && !error && friendRequests.length === 0 && messageNotifications.length === 0 && (
        <p className="no-notifications">No new notifications.</p>
      )}
      <div className="notifications-list">
        {friendRequests.length > 0 && (
          <div className="notification-section">
            <h4>Friend Requests</h4>
            {friendRequests.map((request) => (
              <div key={`friend-${request.senderId._id}`} className="notification-card">
                <div className="notification-info">
                  <img
                    src={getProfilePictureUrl(request.senderId.profilePicture)}
                    alt={`${request.senderId.username}'s profile`}
                    className="avatar"
                    onError={(e) => {
                      console.error(`Notifications: Image load error for ${request.senderId.username}:`, e);
                      e.target.src = '/assets/default-avatar.png';
                    }}
                  />
                  <div className="details">
                    <span className="username">{request.senderId.username}</span>
                    <span className="message">{request.senderId.name} sent you a friend request</span>
                  </div>
                </div>
                <div className="actions">
                  <button
                    className="accept-btn"
                    onClick={() => handleFriendRequestAction(request.senderId._id, 'accept')}
                    disabled={loading}
                  >
                    Accept
                  </button>
                  <button
                    className="reject-btn"
                    onClick={() => handleFriendRequestAction(request.senderId._id, 'reject')}
                    disabled={loading}
                  >
                    Reject
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
        {messageNotifications.length > 0 && (
          <div className="notification-section">
            <h4>Messages</h4>
            {messageNotifications.map((msg) => (
              <div key={`message-${msg._id}`} className="notification-card message-notification">
                <div
                  className="notification-info"
                  onClick={() => handleMessageClick(msg.senderId?._id)}
                  style={{ cursor: 'pointer' }}
                >
                  <img
                    src={getProfilePictureUrl(msg.senderId.profilePicture)}
                    alt={`${msg.senderId.username}'s profile`}
                    className="avatar"
                    onError={(e) => {
                      console.error(`Notifications: Image load error for ${msg.senderId.username}:`, e);
                      e.target.src = '/assets/default-avatar.png';
                    }}
                  />
                  <div className="details">
                    <span className="username">{msg.senderId.username}</span>
                    <span className="message">New message: {msg.content}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Notifications;
